/* A fixed vertical overlay that can fade from either edge. */
(()=>{const ids=['overlayGradientDirection','overlayTopColor','overlayTopOpacity','overlayTopPosition','overlayBottomColor','overlayBottomOpacity','overlayBottomPosition'];const clamp=value=>Math.max(0,Math.min(100,Number(value)||0));const overlay=()=>state.overlayGradient||(state.overlayGradient=defaultOverlayGradient());const read=()=>{const g=overlay();g.enabled=$('overlayGradientEnabled').checked;g.direction=$('overlayGradientDirection').value==='bottom-up'?'bottom-up':'top-down';g.top={color:$('overlayTopColor').value,opacity:clamp($('overlayTopOpacity').value),position:clamp($('overlayTopPosition').value)};g.bottom={color:$('overlayBottomColor').value,opacity:clamp($('overlayBottomOpacity').value),position:clamp($('overlayBottomPosition').value)};for(const id of ['overlayTopOpacity','overlayTopPosition','overlayBottomOpacity','overlayBottomPosition'])$(id).value=clamp($(id).value);const stops=[g.top,g.bottom].sort((a,b)=>a.position-b.position);$('overlayGradientPreview').style.background=`linear-gradient(to right,${stops.map(stop=>{const n=parseInt(stop.color.slice(1),16),r=n>>16&255,green=n>>8&255,b=n&255;return `rgba(${r},${green},${b},${stop.opacity/100}) ${stop.position}%`}).join(',')}),repeating-conic-gradient(#59616a 0 25%,#303842 0 50%) 50%/12px 12px`;changed()};const populate=()=>{const g=overlay();$('overlayGradientEnabled').checked=!!g.enabled;$('overlayGradientDirection').value=g.direction==='bottom-up'?'bottom-up':'top-down';for(const [prefix,stop] of [['overlayTop',g.top],['overlayBottom',g.bottom]]){$(prefix+'Color').value=stop.color;$(prefix+'Hex').value=stop.color.toUpperCase();$(prefix+'Opacity').value=clamp(stop.opacity);$(prefix+'Position').value=clamp(stop.position)}};populate();$('overlayGradientEnabled').addEventListener('input',read);for(const id of ids)$(id).addEventListener('input',read);document.querySelectorAll('.overlay-gradient-editor [data-color-control]').forEach(control=>{const color=control.querySelector('input[type=color]'),hex=control.querySelector('.color-hex');color.addEventListener('input',()=>{hex.value=color.value.toUpperCase();read()});hex.addEventListener('change',()=>{if(/^#[0-9a-f]{6}$/i.test(hex.value.trim()))color.value=hex.value.trim();hex.value=color.value.toUpperCase();read()})});read()})();
